//! The curve models against an independent oracle and against OpenSSL.
//!
//! The oracle is the textbook affine group law (chord and tangent, with one
//! inversion per operation), short enough to check by reading; every
//! formula of the projective and Jacobian models is compared with it. The
//! generator is checked to be on the curve and of the stated order, and the
//! scalar multiplication against key pairs generated by OpenSSL.
#![allow(clippy::many_single_char_names)]

use std::{fs, path::Path};

use proptest::prelude::*;

use super::{
    CurveParams, P256, P384, P521,
    affine::Affine,
    jacobian::Jacobian,
    mul::{mul, mul_generator},
    params,
    projective::Projective,
};
use crate::field::PrimeField;

/// The affine group law: $\lambda = (y_2 - y_1) / (x_2 - x_1)$, or
/// $(3 x_1^2 - 3) / (2 y_1)$ when doubling; $x_3 = \lambda^2 - x_1 - x_2$,
/// $y_3 = \lambda (x_1 - x_3) - y_1$.
fn reference_add<C>(p: &Affine<C>, q: &Affine<C>) -> Affine<C>
where
    C: CurveParams,
{
    let (Some((x1, y1)), Some((x2, y2))) = (p.coordinates(), q.coordinates())
    else {
        return if p.is_identity().to_bool_vartime() {
            *q
        } else {
            *p
        };
    };
    let lambda = if x1 == x2 {
        if y1 != y2 || y1 == C::Base::ZERO {
            return Affine::identity();
        }
        let three = C::Base::from_u64(3);
        (three * x1.square() - three) * y1.double().invert()
    } else {
        (y2 - y1) * (x2 - x1).invert()
    };
    let x3 = lambda.square() - x1 - x2;
    let y3 = lambda * (x1 - x3) - y1;
    let (point, on_curve) = Affine::from_coordinates(x3, y3);
    assert!(on_curve.to_bool_vartime(), "reference left the curve");
    point
}

/// $kP$ by repeated reference additions, for small $k$.
fn reference_small_mul<C>(p: &Affine<C>, k: u64) -> Affine<C>
where
    C: CurveParams,
{
    (0..k).fold(Affine::identity(), |acc, _| reference_add(&acc, p))
}

fn affine<C>(p: &Projective<C>) -> Affine<C>
where
    C: CurveParams,
{
    Affine::from(*p)
}

fn scalar<C>(k: u64) -> C::Scalar
where
    C: CurveParams,
{
    C::Scalar::from_u64(k)
}

fn check_constants<C>()
where
    C: CurveParams,
{
    assert!(params::element::<C::Base>(C::B).is_some(), "{} b", C::NAME);
    assert!(
        params::element::<C::Base>(C::GX).is_some(),
        "{} gx",
        C::NAME
    );
    assert!(
        params::element::<C::Base>(C::GY).is_some(),
        "{} gy",
        C::NAME
    );
    let g = Affine::<C>::generator();
    assert!(
        g.is_on_curve().to_bool_vartime(),
        "{} G on the curve",
        C::NAME
    );
    // n G = O: the scalar n is 0, so check (n - 1) G = -G and that adding G
    // gives the identity.
    let minus_one = -C::Scalar::ONE;
    let p = mul_generator::<C>(&minus_one);
    assert_eq!(affine(&p), g.neg(), "{} (n - 1) G", C::NAME);
    assert!(
        p.add_affine(&g).is_identity().to_bool_vartime(),
        "{} n G",
        C::NAME
    );
    assert!(
        mul_generator::<C>(&C::Scalar::ZERO)
            .is_identity()
            .to_bool_vartime()
    );
}

#[test]
fn constants_and_order() {
    check_constants::<P256>();
    check_constants::<P384>();
    check_constants::<P521>();
}

/// The identity behaves as one in every model and formula.
fn check_identity<C>()
where
    C: CurveParams,
{
    let g = Projective::<C>::generator();
    let o = Projective::<C>::identity();
    assert_eq!(g.add(&o), g);
    assert_eq!(o.add(&g), g);
    assert!(o.double().is_identity().to_bool_vartime());
    assert!(g.add(&g.neg()).is_identity().to_bool_vartime());
    assert_eq!(g.add_affine(&Affine::identity()), g);
    assert_eq!(o.add_affine(&Affine::generator()), g);
    assert_eq!(Affine::from(o), Affine::<C>::identity());
    assert!(Jacobian::from(o).is_identity().to_bool_vartime());
    assert!(
        Projective::from(Jacobian::<C>::identity())
            .is_identity()
            .to_bool_vartime()
    );
    assert_eq!(Affine::from(Jacobian::<C>::identity()), Affine::identity());
    let jg = Jacobian::from(Affine::<C>::generator());
    assert_eq!(Affine::from(jg.add_vartime(&jg.neg())), Affine::identity());
    assert_eq!(
        Affine::from(jg.add_vartime(&Jacobian::identity())),
        Affine::generator()
    );
    assert!(
        Jacobian::<C>::identity()
            .double()
            .is_identity()
            .to_bool_vartime()
    );
}

#[test]
fn identity() {
    check_identity::<P256>();
    check_identity::<P384>();
    check_identity::<P521>();
}

/// Small multiples of G by every formula against the affine reference.
fn check_small_multiples<C>()
where
    C: CurveParams,
{
    let g = Affine::<C>::generator();
    let mut proj = Projective::<C>::identity();
    let mut jac = Jacobian::<C>::identity();
    for k in 1..=12u64 {
        proj = proj.add_affine(&g);
        jac = jac.add_vartime(&Jacobian::from(g));
        let expected = reference_small_mul(&g, k);
        assert_eq!(affine(&proj), expected, "{} {k}G mixed", C::NAME);
        assert_eq!(Affine::from(jac), expected, "{} {k}G jacobian", C::NAME);
        assert_eq!(
            affine(&mul_generator::<C>(&scalar::<C>(k))),
            expected,
            "{} {k}G mul",
            C::NAME
        );
        let doubled = reference_add(&expected, &expected);
        assert_eq!(affine(&proj.double()), doubled, "{} 2({k}G)", C::NAME);
        assert_eq!(
            Affine::from(jac.double()),
            doubled,
            "{} 2({k}G) jacobian",
            C::NAME
        );
    }
}

#[test]
fn small_multiples() {
    check_small_multiples::<P256>();
    check_small_multiples::<P384>();
    check_small_multiples::<P521>();
}

/// A scalar from arbitrary bytes, with the bits above the order's length
/// cleared; `None` when still not below the order.
fn scalar_from<C>(bytes: &[u8]) -> Option<C::Scalar>
where
    C: CurveParams,
{
    let mut b = bytes.get(..C::Scalar::BYTES)?.to_vec();
    let spare = C::Scalar::BYTES * 8 - C::Scalar::BITS as usize;
    if let Some(first) = b.first_mut() {
        *first &= 0xff >> spare;
    }
    let (s, valid) = C::Scalar::from_bytes_be(&b);
    valid.to_bool_vartime().then_some(s)
}

/// The group laws through the scalar multiplication, and every model and map
/// on random points.
fn check_laws<C>(a: &[u8], b: &[u8])
where
    C: CurveParams,
{
    let (Some(k1), Some(k2)) = (scalar_from::<C>(a), scalar_from::<C>(b))
    else {
        return;
    };
    let p = mul_generator::<C>(&k1);
    let q = mul_generator::<C>(&k2);
    let (ap, aq) = (affine(&p), affine(&q));
    assert!(ap.is_on_curve().to_bool_vartime());

    // (k1 + k2) G = k1 G + k2 G, and k1 (k2 G) = (k1 k2) G.
    assert_eq!(
        mul_generator::<C>(&(k1 + k2)),
        p.add(&q),
        "{} additivity",
        C::NAME
    );
    assert_eq!(
        mul(&q, &k1),
        mul_generator::<C>(&(k1 * k2)),
        "{} composition",
        C::NAME
    );

    // Every addition and doubling formula against the reference.
    let sum = reference_add(&ap, &aq);
    assert_eq!(affine(&p.add(&q)), sum, "{} projective add", C::NAME);
    assert_eq!(affine(&p.add_affine(&aq)), sum, "{} mixed add", C::NAME);
    let (jp, jq) = (Jacobian::from(ap), Jacobian::from(aq));
    assert_eq!(
        Affine::from(jp.add_vartime(&jq)),
        sum,
        "{} jacobian add",
        C::NAME
    );
    let twice = reference_add(&ap, &ap);
    assert_eq!(affine(&p.double()), twice, "{} projective double", C::NAME);
    assert_eq!(
        Affine::from(jp.double()),
        twice,
        "{} jacobian double",
        C::NAME
    );

    // The maps commute: Jacobian -> projective -> affine is Jacobian -> affine,
    // and projective -> Jacobian -> affine is projective -> affine, also for
    // non-normalized coordinates (a Jacobian sum has Z != 1).
    let js = jp.add_vartime(&jq);
    assert_eq!(Affine::from(Projective::from(js)), Affine::from(js));
    assert_eq!(Affine::from(Jacobian::from(p)), ap);
    assert_eq!(Projective::from(ap), p);

    // Encoding round trip, and rejection of a point off the curve.
    let enc = ap.to_uncompressed();
    assert_eq!(Affine::<C>::from_uncompressed(&enc), Some(ap));
    let mut off = enc.clone();
    if let Some(last) = off.last_mut() {
        *last ^= 1;
    }
    assert_eq!(
        Affine::<C>::from_uncompressed(&off),
        None,
        "{} off-curve",
        C::NAME
    );
}

fn bytes() -> impl Strategy<Value = Vec<u8>> {
    prop::collection::vec(any::<u8>(), 66)
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(16))]

    #[test]
    fn laws_p256(a in bytes(), b in bytes()) {
        check_laws::<P256>(&a, &b);
    }

    #[test]
    fn laws_p384(a in bytes(), b in bytes()) {
        check_laws::<P384>(&a, &b);
    }

    #[test]
    fn laws_p521(a in bytes(), b in bytes()) {
        check_laws::<P521>(&a, &b);
    }
}

/// Decoding rejects a wrong length, a wrong prefix and a coordinate that is
/// not below p.
fn check_decoding<C>()
where
    C: CurveParams,
{
    let enc = Affine::<C>::generator().to_uncompressed();
    assert_eq!(Affine::<C>::from_uncompressed(&enc[..enc.len() - 1]), None);
    let mut prefix = enc.clone();
    prefix[0] = 0x02;
    assert_eq!(Affine::<C>::from_uncompressed(&prefix), None);
    let mut big = enc.clone();
    for byte in &mut big[1..=C::Base::BYTES] {
        *byte = 0xff;
    }
    assert_eq!(Affine::<C>::from_uncompressed(&big), None);
    assert_eq!(Affine::<C>::identity().to_uncompressed(), vec![0x00]);
    assert_eq!(Affine::<C>::from_uncompressed(&[0x00]), None);
}

#[test]
fn decoding() {
    check_decoding::<P256>();
    check_decoding::<P384>();
    check_decoding::<P521>();
}

/// d G = Q for key pairs generated by OpenSSL
/// (`scripts/gen-ec-vectors.sh`).
#[test]
fn openssl_key_pairs() {
    fn check<C>(d_hex: &str, q_hex: &str)
    where
        C: CurveParams,
    {
        let d_hex = d_hex.trim_start_matches('0');
        let padded = format!("{d_hex:0>width$}", width = 2 * C::Scalar::BYTES);
        let d = params::element::<C::Scalar>(&padded).expect("private scalar");
        let q = (0..q_hex.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&q_hex[i..i + 2], 16).unwrap())
            .collect::<Vec<u8>>();
        assert_eq!(
            affine(&mul_generator::<C>(&d)).to_uncompressed(),
            q,
            "{}",
            C::NAME
        );
    }
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/keys/keypairs.txt");
    let mut seen = 0;
    for line in fs::read_to_string(path).unwrap().lines() {
        let fields: Vec<&str> = line.split_whitespace().collect();
        match fields.as_slice() {
            ["P-256", d, q] => check::<P256>(d, q),
            ["P-384", d, q] => check::<P384>(d, q),
            ["P-521", d, q] => check::<P521>(d, q),
            _ => continue,
        }
        seen += 1;
    }
    assert_eq!(seen, 12);
}
